public class ArithmeticTreeEvaluatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Expr sumOfProduct = new Add(new Num(1), new Mul(new Num(2), new Num(3)));
        check("eval of a nested sum", 7.0, ArithmeticTreeEvaluator.eval(sumOfProduct));
        check("render of a nested sum", "(1.0 + (2.0 * 3.0))", ArithmeticTreeEvaluator.render(sumOfProduct));
        check("nodeCount of a nested sum", 5, ArithmeticTreeEvaluator.nodeCount(sumOfProduct));

        Expr negated = new Neg(new Add(new Num(2), new Num(0.5)));
        check("eval of a negated sum", -2.5, ArithmeticTreeEvaluator.eval(negated));
        check("render of a negated sum", "-(2.0 + 0.5)", ArithmeticTreeEvaluator.render(negated));

        Expr product = new Mul(new Neg(new Num(4)), new Num(0.25));
        check("eval of a product with a negated leaf", -1.0, ArithmeticTreeEvaluator.eval(product));
        check("render of a product with a negated leaf", "(-4.0 * 0.25)", ArithmeticTreeEvaluator.render(product));

        String nulls = ArithmeticTreeEvaluator.eval(null)
                + "|" + ArithmeticTreeEvaluator.render(null)
                + "|" + ArithmeticTreeEvaluator.nodeCount(null);
        check("null nodes are handled", "0.0|?|0", nulls);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

