/**
 * TASK: Complete ArithmeticTreeEvaluator, which walks a small expression
 * hierarchy with recursion and pattern matching for instanceof. The Expr
 * interface and its four records above are provided -- do not change them.
 *
 * An expression is a TREE: Add and Mul hold two sub-expressions, Neg holds
 * one, and Num is a leaf. Each method tests the runtime type of the node it
 * is given and recurses into the children.
 *
 * Rules:
 *   - eval:      Num is its value, Add adds, Mul multiplies, Neg negates;
 *                null or any other Expr evaluates to 0.0
 *   - render:    Num is String.valueOf(value) ("2.0"), Add is
 *                "(left + right)", Mul is "(left * right)", Neg is
 *                "-" + the rendered inner expression (no extra brackets);
 *                null or any other Expr renders as "?"
 *   - nodeCount: how many nodes the tree holds in total; null counts 0
 *
 * Example: Add(Num(1), Mul(Num(2), Num(3))) evaluates to 7.0, renders as
 *   "(1.0 + (2.0 * 3.0))" and has a nodeCount of 5.
 */
interface Expr {
}

record Num(double value) implements Expr {
}

record Add(Expr left, Expr right) implements Expr {
}

record Mul(Expr left, Expr right) implements Expr {
}

record Neg(Expr inner) implements Expr {
}

public class ArithmeticTreeEvaluator {

    public static double eval(Expr e) {
        if (e instanceof Num num) {
            return num.value();
        }
        if (e instanceof Add add) {
            return eval(add.left()) + eval(add.right());
        }
        if (e instanceof Mul mul) {
            return eval(mul.left()) * eval(mul.right());
        }
        if (e instanceof Neg neg) {
            return -eval(neg.inner());
        }
        return 0.0;
    }

    public static String render(Expr e) {
        if (e instanceof Num num) {
            return String.valueOf(num.value());
        }
        if (e instanceof Add add) {
            return "(" + render(add.left()) + " + " + render(add.right()) + ")";
        }
        if (e instanceof Mul mul) {
            return "(" + render(mul.left()) + " * " + render(mul.right()) + ")";
        }
        if (e instanceof Neg neg) {
            return "-" + render(neg.inner());
        }
        return "?";
    }

    public static int nodeCount(Expr e) {
        if (e instanceof Num) {
            return 1;
        }
        if (e instanceof Add add) {
            return 1 + nodeCount(add.left()) + nodeCount(add.right());
        }
        if (e instanceof Mul mul) {
            return 1 + nodeCount(mul.left()) + nodeCount(mul.right());
        }
        if (e instanceof Neg neg) {
            return 1 + nodeCount(neg.inner());
        }
        return 0;
    }
}
